import{_ as a,o as e,c as r,a5 as d}from"./chunks/framework.CXroN2RO.js";const c=JSON.parse('{"title":"この技術辞典について","description":"","frontmatter":{"title":"この技術辞典について","study":{"source":"統合ガイド","status":"published","generated":true,"catalog":false,"section":"reference","format":"index","domain":"guide"}},"headers":[],"relativePath":"guide/about.md","filePath":"guide/about.md"}'),o={name:"guide/about.md"};function i(s,t,n,h,l,u){return e(),r("div",null,[...t[0]||(t[0]=[d('<h1 id="この技術辞典について" tabindex="-1">この技術辞典について <a class="header-anchor" href="#この技術辞典について" aria-label="Permalink to &quot;この技術辞典について&quot;">​</a></h1><p>コンピュータの内部から、言語、開発ツール、3DCG、ゲーム開発までをつなぐ個人の技術ノートです。自分が調べ直すための辞典を、一般公開しています。</p><h2 id="目的に応じた3つの入口" tabindex="-1">目的に応じた3つの入口 <a class="header-anchor" href="#目的に応じた3つの入口" aria-label="Permalink to &quot;目的に応じた3つの入口&quot;">​</a></h2><table tabindex="0"><thead><tr><th>入口</th><th>調べられること</th></tr></thead><tbody><tr><td><a href="/study/">技術辞典</a></td><td>用語の意味、仕組み、内部動作、比較、注意点。分野と名前から調べます。</td></tr><tr><td><a href="/study/learn/">学習ガイド</a></td><td>前提知識、到達目標、読む順番。詳しい説明は辞典の本文へつなぎます。</td></tr><tr><td><a href="/study/practice/">実践・サンプル</a></td><td>制作手順、コード例、演習。動かしたり考えたりして確かめます。</td></tr></tbody></table><p>分野は扱うテーマ、入口はページの役割です。同じテーマの学習ガイドと本文があっても、用途を分けて案内します。各本文にある「関連する学習ガイド・実践」から行き来できます。</p><h2 id="記事の状態と確認範囲" tabindex="-1">記事の状態と確認範囲 <a class="header-anchor" href="#記事の状態と確認範囲" aria-label="Permalink to &quot;記事の状態と確認範囲&quot;">​</a></h2><p>「草稿」は増補・推敲中の解説、「学習計画・概要」は学ぶ範囲と演習の案内です。学習計画があるだけの分野を、辞典本文が整っている分野と同じ扱いにはしていません。ブラウザやネットワークなど、専用の本文がまだない分野も明示します。</p><p>公開中という状態は、コードの実行や技術内容の全面的な検証を保証しません。対象の言語・規格・エンジン・OSと、実行確認の範囲は個々の本文に従ってください。「モデル検証済み」等の記録は、そのページに書かれた確認範囲に限ります。</p><p>標準で保証されること、典型的な実装、実測結果、設計上の助言を区別して読みます。元原稿の出典と検証記録も保っています。</p><h2 id="探し方" tabindex="-1">探し方 <a class="header-anchor" href="#探し方" aria-label="Permalink to &quot;探し方&quot;">​</a></h2><p>入口ごとの索引は、その入口に属するページのタイトル・別名を絞り込みます。画面上部の全文検索はサイト全体が対象です。<a href="/study/terms/">用語・別名</a>からも説明へ進めます。</p><p>元の教本の章順は学習ガイドに残し、辞典では主題の名前を使います。再編前のURLからも、同じページを開けます。</p><p>誤りや改善点は、<a href="https://github.com/sny0/sny0.github.io/tree/main/study" target="_blank" rel="noreferrer">このサイトのソース</a>から確認できます。</p>',13)])])}const _=a(o,[["render",i]]);export{c as __pageData,_ as default};
